INSERT INTO `wp_snippets` (`id`, `name`, `description`, `code`, `tags`, `scope`, `condition_id`, `priority`, `active`, `modified`, `revision`, `cloud_id`) VALUES
(1, 'Κάντε τα ονόματα αρχείων μεταφόρτωσης πεζά', 'Διασφαλίζει ότι οι μεταφορτώσεις εικόνων και αρχείων έχουν όνομα με πεζούς χαρακτήρες.\n\nΑυτό είναι ένα δείγμα αποσπάσματος. Μπορείτε να το χρησιμοποιήσετε, να το επεξεργαστείτε ή να το αφαιρέσετε.', 'add_filter( \'sanitize_file_name\', \'mb_strtolower\' );', 'sample, media', 'global', 0, 10, 0, '2026-08-27 23:20:27', 1, NULL),
(2, 'Απενεργοποίηση διαχειριστικής μπάρας', 'Απενεργοποιεί τη μπάρα διαχείρισης του WordPress για όλους εκτός από τους διαχειριστές.\n\nΑυτό είναι ένα δείγμα αποσπάσματος. Μπορείτε να το χρησιμοποιήσετε, να το επεξεργαστείτε ή να το αφαιρέσετε.', 'add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );', 'sample, admin-bar', 'front-end', 0, 10, 0, '2026-08-27 23:20:27', 1, NULL),
(3, 'Επιτρέψτε τα smilies', 'Επιτρέπει τη μετατροπή σε smiley σε όλα τα σημεία.\n\nΑυτό είναι ένα δείγμα αποσπάσματος. Μπορείτε να το χρησιμοποιήσετε, να το επεξεργαστείτε ή να το αφαιρέσετε.', 'add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );', 'sample', 'global', 0, 10, 0, '2026-08-27 23:20:27', 1, NULL),
(4, 'Τρέχον έτος', 'Shortcode για την εισαγωγή του τρέχοντος έτους σε ένα άρθρο ή σελίδα.\n\nΑυτό είναι ένα δείγμα αποσπάσματος. Μπορείτε να το χρησιμοποιήσετε, να το επεξεργαστείτε ή να το αφαιρέσετε.', '<?php echo date( \'Y\' ); ?>', 'sample, dates', 'content', 0, 10, 0, '2026-08-27 23:20:27', 1, NULL),
(5, 'Χρέωση Αντικαταβολής ανά Χώρα', '', 'add_action( \'woocommerce_cart_calculate_fees\', \'add_cod_fee_based_on_country\' );\nfunction add_cod_fee_based_on_country( $cart ) {\n    if ( is_admin() && ! defined( \'DOING_AJAX\' ) ) {\n        return;\n    }\n\n    // Ελέγχουμε αν η μέθοδος πληρωμής που έχει επιλεγεί είναι η αντικαταβολή (cod)\n    $chosen_payment_method = WC()->session->get( \'chosen_payment_method\' );\n    if ( \'cod\' !== $chosen_payment_method ) {\n        return;\n    }\n\n    // Παίρνουμε τη χώρα αποστολής\n    $shipping_country = WC()->customer->get_shipping_country();\n    if ( empty( $shipping_country ) ) {\n        $shipping_country = WC()->customer->get_billing_country();\n    }\n\n    $cod_fee = 0;\n\n    // Ορίζουμε τις χρεώσεις ανάλογα με τη χώρα\n    if ( \'GR\' === $shipping_country ) {\n        $cod_fee = 3.5; // Κόστος αντικαταβολής για Ελλάδα\n        $fee_name = \'Έξοδα Αντικαταβολής (Ελλάδα)\';\n    } else {\n        $cod_fee = 10.0; // Κόστος αντικαταβολής για εξωτερικό\n        $fee_name = \'Έξοδα Αντικαταβολής (Εξωτερικό)\';\n    }\n\n    if ( $cod_fee > 0 ) {\n        $cart->add_fee( $fee_name, $cod_fee, true );\n    }\n}\n\n// Ανανέωση του checkout όταν αλλάζει ο τρόπος πληρωμής, για να φαίνεται αμέσως η χρέωση\nadd_action( \'wp_footer\', \'cod_fee_refresh_checkout\' );\nfunction cod_fee_refresh_checkout() {\n    if ( is_checkout() ) {\n        ?>\n        <script type=\"text/javascript\">\n            jQuery( function( $ ) {\n                $( \'form.checkout\' ).on( \'change\', \'input[name=\"payment_method\"]\', function() {\n                    $( document.body ).trigger( \'update_checkout\' );\n                });\n            });\n        </script>\n        <?php\n    }\n}', '', 'global', 0, 10, 1, '2026-08-27 23:23:33', 1, NULL);
