INSERT INTO `wp_wc_admin_notes` (`note_id`, `name`, `type`, `locale`, `title`, `content`, `content_data`, `status`, `source`, `date_created`, `date_reminder`, `is_snoozable`, `layout`, `image`, `is_deleted`, `is_read`, `icon`) VALUES
(1, 'wc-refund-returns-page', 'info', 'en_US', 'Δημιουργήστε μια σελίδα Πολιτικής επιστροφής χρημάτων και προϊόντων για να αυξήσετε την αξιοπιστία του καταστήματός σας.', 'Έχουμε δημιουργήσει για εσάς ένα προσχέδιο της σελίδας Πολιτικής επιστροφής χρημάτων και προϊόντων. Παρακαλούμε ελέγξτε την και ενημερώστε την όπως αρμόζει στο κατάστημά σας.', '{}', 'unactioned', 'woocommerce-core', '2025-12-30 18:44:58', NULL, 0, 'plain', '', 0, 1, 'info'),
(2, 'wc-refund-returns-page', 'info', 'en_US', 'Δημιουργήστε μια σελίδα Πολιτικής επιστροφής χρημάτων και προϊόντων για να αυξήσετε την αξιοπιστία του καταστήματός σας.', 'Έχουμε δημιουργήσει για εσάς ένα προσχέδιο της σελίδας Πολιτικής επιστροφής χρημάτων και προϊόντων. Παρακαλούμε ελέγξτε την και ενημερώστε την όπως αρμόζει στο κατάστημά σας.', '{}', 'unactioned', 'woocommerce-core', '2025-12-30 18:44:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(3, 'wc-admin-email-improvements', 'info', 'en_US', 'Store emails have had an upgrade!', 'We’ve made some exciting improvements to our email templates, including modern, shopper-friendly designs and new customization options. And if you’re using a block theme, you can automatically sync your theme styles! Head to your email settings to explore the new features.', '{}', 'unactioned', 'woocommerce-admin', '2025-12-30 18:45:01', NULL, 0, 'plain', '', 0, 1, 'info'),
(4, 'your-first-product', 'info', 'en_US', 'Your first product', 'That’s huge! You’re well on your way to building a successful online store — now it’s time to think about how you’ll fulfill your orders.<br /><br />Read our shipping guide to learn best practices and options for putting together your shipping strategy. And for WooCommerce stores in the United States, you can print discounted shipping labels via USPS with <a href=\"https://href.li/?https://woocommerce.com/shipping\" target=\"_blank\">WooCommerce Shipping</a>.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(5, 'wc-admin-optimizing-the-checkout-flow', 'info', 'en_US', 'Optimizing the checkout flow', 'It’s crucial to get your store’s checkout as smooth as possible to avoid losing sales. Let’s take a look at how you can optimize the checkout experience for your shoppers.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(6, 'wc-payments-qualitative-feedback', 'info', 'en_US', 'WooPayments setup - let us know what you think', 'Congrats on enabling WooPayments for your store. Please share your feedback in this 2 minute survey to help us improve the setup process.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(7, 'share-your-feedback-on-paypal', 'info', 'en_US', 'Share your feedback on PayPal', 'Share your feedback in this 2 minute survey about how we can make the process of accepting payments more useful for your store.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(8, 'google_listings_and_ads_install', 'marketing', 'en_US', 'Drive traffic and sales with Google', 'Reach online shoppers to drive traffic and sales for your store by showcasing products across Google, for free or with ads.', '{}', 'unactioned', 'woocommerce.com', '2026-09-09 13:35:44', NULL, 0, 'plain', '', 0, 0, 'info'),
(9, 'wc-subscriptions-security-update-3-0-15', 'info', 'en_US', 'WooCommerce Subscriptions security update!', 'We recently released an important security update to WooCommerce Subscriptions. To ensure your site’s data is protected, please upgrade <strong>WooCommerce Subscriptions to version 3.0.15</strong> or later.<br /><br />Click the button below to view and update to the latest Subscriptions version, or log in to <a href=\"https://woocommerce.com/my-dashboard\">WooCommerce.com Dashboard</a> and navigate to your <strong>Downloads</strong> page.<br /><br />We recommend always using the latest version of WooCommerce Subscriptions, and other software running on your site, to ensure maximum security.<br /><br />If you have any questions we are here to help — just <a href=\"https://woocommerce.com/my-account/create-a-ticket/\">open a ticket</a>.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(10, 'woocommerce-core-update-5-4-0', 'info', 'en_US', 'Update to WooCommerce 5.4.1 now', 'WooCommerce 5.4.1 addresses a checkout issue discovered in WooCommerce 5.4. We recommend upgrading to WooCommerce 5.4.1 as soon as possible.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(11, 'wcpay-promo-2020-11', 'marketing', 'en_US', 'wcpay-promo-2020-11', 'wcpay-promo-2020-11', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(12, 'wcpay-promo-2020-12', 'marketing', 'en_US', 'wcpay-promo-2020-12', 'wcpay-promo-2020-12', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(13, 'ppxo-pps-upgrade-paypal-payments-1', 'info', 'en_US', 'Get the latest PayPal extension for WooCommerce', 'Heads up! There’s a new PayPal on the block!<br /><br />Now is a great time to upgrade to our latest <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">PayPal extension</a> to continue to receive support and updates with PayPal.<br /><br />Get access to a full suite of PayPal payment methods, extensive currency and country coverage, and pay later options with the all-new PayPal extension for WooCommerce.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(14, 'ppxo-pps-upgrade-paypal-payments-2', 'info', 'en_US', 'Upgrade your PayPal experience!', 'Get access to a full suite of PayPal payment methods, extensive currency and country coverage, offer subscription and recurring payments, and the new PayPal pay later options.<br /><br />Start using our <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">latest PayPal today</a> to continue to receive support and updates.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(15, 'woocommerce-core-sqli-july-2021-need-to-update', 'update', 'en_US', 'Action required: Critical vulnerabilities in WooCommerce', 'In response to a critical vulnerability identified on July 13, 2021, we are working with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br />Our investigation into this vulnerability is ongoing, but <strong>we wanted to let you know now about the importance of updating immediately</strong>.<br /><br />For more information on which actions you should take, as well as answers to FAQs, please urgently review our blog post detailing this issue.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(16, 'woocommerce-blocks-sqli-july-2021-need-to-update', 'update', 'en_US', 'Action required: Critical vulnerabilities in WooCommerce Blocks', 'In response to a critical vulnerability identified on July 13, 2021, we are working with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br />Our investigation into this vulnerability is ongoing, but <strong>we wanted to let you know now about the importance of updating immediately</strong>.<br /><br />For more information on which actions you should take, as well as answers to FAQs, please urgently review our blog post detailing this issue.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(17, 'woocommerce-core-sqli-july-2021-store-patched', 'update', 'en_US', 'Solved: Critical vulnerabilities patched in WooCommerce', 'In response to a critical vulnerability identified on July 13, 2021, we worked with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br /><strong>Your store has been updated to the latest secure version(s)</strong>. For more information and answers to FAQs, please review our blog post detailing this issue.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(18, 'woocommerce-blocks-sqli-july-2021-store-patched', 'update', 'en_US', 'Solved: Critical vulnerabilities patched in WooCommerce Blocks', 'In response to a critical vulnerability identified on July 13, 2021, we worked with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br /><strong>Your store has been updated to the latest secure version(s)</strong>. For more information and answers to FAQs, please review our blog post detailing this issue.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(19, 'habit-moment-survey', 'marketing', 'en_US', 'We’re all ears! Share your experience so far with WooCommerce', 'We’d love your input to shape the future of WooCommerce together. Feel free to share any feedback, ideas or suggestions that you have.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(20, 'woocommerce-core-paypal-march-2022-updated', 'update', 'en_US', 'Security auto-update of WooCommerce', '<strong>Your store has been updated to the latest secure version of WooCommerce</strong>. We worked with WordPress to deploy PayPal Standard security updates for stores running WooCommerce (version 3.5 to 6.3). It’s recommended to disable PayPal Standard, and use <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">PayPal Payments</a> to accept PayPal.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(21, 'woocommerce-core-paypal-march-2022-updated-nopp', 'update', 'en_US', 'Security auto-update of WooCommerce', '<strong>Your store has been updated to the latest secure version of WooCommerce</strong>. We worked with WordPress to deploy security updates related to PayPal Standard payment gateway for stores running WooCommerce (version 3.5 to 6.3).', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(22, 'pinterest_03_2022_update', 'marketing', 'en_US', 'Your Pinterest for WooCommerce plugin is out of date!', 'Update to the latest version of Pinterest for WooCommerce to continue using this plugin and keep your store connected with Pinterest. To update, visit <strong>Plugins &gt; Installed Plugins</strong>, and click on “update now” under Pinterest for WooCommerce.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(23, 'store_setup_survey_survey_q2_2022', 'survey', 'en_US', 'How is your store setup going?', 'Our goal is to make sure you have all the right tools to start setting up your store in the smoothest way possible.\r\nWe’d love to know if we hit our mark and how we can improve. To collect your thoughts, we made a 2-minute survey.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(24, 'needs-update-eway-payment-gateway-rin-2022-12-20', 'update', 'en_US', 'Security vulnerability patched in WooCommerce Eway Gateway', 'In response to a potential vulnerability identified in WooCommerce Eway Gateway versions 3.1.0 to 3.5.0, we’ve worked to deploy security fixes and have released an updated version.\r\nNo external exploits have been detected, but we recommend you update to your latest supported version 3.1.26, 3.2.3, 3.3.1, 3.4.6, or 3.5.1', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(25, 'updated-eway-payment-gateway-rin-2022-12-20', 'update', 'en_US', 'WooCommerce Eway Gateway has been automatically updated', 'Your store is now running the latest secure version of WooCommerce Eway Gateway. We worked with the WordPress Plugins team to deploy a software update to stores running WooCommerce Eway Gateway (versions 3.1.0 to 3.5.0) in response to a security vulnerability that was discovered.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(26, 'ecomm-wc-navigation-survey-2023', 'info', 'en_US', 'Navigating WooCommerce on WordPress.com', 'We are improving the WooCommerce navigation on WordPress.com and would love your help to make it better! Please share your experience with us in this 2-minute survey.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(27, 'woopay-beta-merchantrecruitment-04MAY23', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'WooPay, a new express checkout feature built into WooCommerce Payments, is now available —and we’re inviting you to be one of the first to try it. \r\n<br><br>\r\nBoost conversions by offering your customers a simple, secure way to pay with a single click.\r\n<br><br>\r\nGet started in seconds.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(28, 'woocommerce-wcpay-march-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Payments', '<strong>Your store requires a security update for WooCommerce Payments</strong>. Please update to the latest version of WooCommerce Payments immediately to address a potential vulnerability discovered on March 22. For more information on how to update, visit this WooCommerce Developer Blog Post.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(29, 'tap_to_pay_iphone_q2_2023_no_wcpay', 'marketing', 'en_US', 'Accept in-person contactless payments on your iPhone', 'Tap to Pay on iPhone and WooCommerce Payments is quick, secure, and simple to set up — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(30, 'woocommerce-WCPreOrders-april-2023-update-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Pre-Orders extension', '<strong>Your store requires a security update for the WooCommerce Pre-Orders extension</strong>. Please update the WooCommerce Pre-Orders extension immediately to address a potential vulnerability discovered on April 11.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(31, 'woopay-beta-merchantrecruitment-update-04MAY23', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'WooPay, a new express checkout feature built into WooCommerce Payments, is now available — and you’re invited to try it. \r\n<br /><br />\r\nBoost conversions by offering your customers a simple, secure way to pay with a single click.\r\n<br /><br />\r\nUpdate WooCommerce Payments to get started.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(32, 'woopay-beta-existingmerchants-noaction-27APR23', 'info', 'en_US', 'WooPay is back!', 'Thanks for previously trying WooPay, the express checkout feature built into WooCommerce Payments. We’re excited to announce that WooPay availability has resumed. No action is required on your part.\r\n<br /><br />\r\nYou can now continue boosting conversions by offering your customers a simple, secure way to pay with a single click.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(33, 'woopay-beta-existingmerchants-update-27APR23', 'info', 'en_US', 'WooPay is back!', 'Thanks for previously trying WooPay, the express checkout feature built into WooCommerce Payments. We’re excited to announce that WooPay availability has resumed.\r\n<br /><br />\r\n\r\nUpdate to the latest WooCommerce Payments version to continue boosting conversions by offering your customers a simple, secure way to pay with a single click.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(34, 'woopay-beta-merchantrecruitment-short-04MAY23', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(35, 'woopay-beta-merchantrecruitment-short-update-04MAY23', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'Be one of the first to try WooPay, our new express checkout feature. <br>Boost conversions by letting customers pay with a single click. <br><br>Update to the latest version of WooCommerce Payments to get started.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(36, 'woopay-beta-merchantrecruitment-short-09MAY23', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(37, 'woopay-beta-merchantrecruitment-short-update-09MAY23', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'Be one of the first to try WooPay, our new express checkout feature. <br>Boost conversions by letting customers pay with a single click. <br><br>Update to the latest version of WooCommerce Payments to get started.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(38, 'woocommerce-WCSubscriptions-June-2023-updated-needed', 'marketing', 'en_US', 'Action required: Security update of WooCommerce Subscriptions', '<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(39, 'woocommerce-WCReturnsWarranty-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Returns and Warranty Requests extension', '<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(40, 'woocommerce-WCOPC-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce One Page Checkout', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(41, 'woocommerce-WCGC-July-2023-update-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce GoCardless Extension', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(42, 'woocommerce-shipping-fedex-api-outage-2023-07-16', 'warning', 'en_US', 'Scheduled FedEx API outage — July 2023', 'On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(43, 'wcship-2023-07-hazmat-update-needed', 'update', 'en_US', 'Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension', '<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(44, 'woocommerce-WCStripe-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe plugin', '<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(45, 'woocommerce-WCStripe-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooCommerce Stripe plugin', '<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(46, 'woocommerce-WooPayments-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooPayments (WooCommerce Payments) plugin', '<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(47, 'avalara_q3-2023_noAvaTax', 'marketing', 'en_US', 'Automatically calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(48, 'woocommerce-usermeta-Sept2023-productvendors', 'update', 'en_US', 'Your store requires a security update', '<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(49, 'woocommerce-STRIPE-Oct-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe Gateway', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(50, 'amazon-mcf-reviews-2023-12-07', 'marketing', 'en_US', 'Enjoying Amazon MCF for WooCommerce?', 'We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(51, 'remove_estimated_deposits_2024', 'marketing', 'en_US', 'Estimated deposits are going away', 'To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(52, 'sirt-woo-2024-11-xss-admin', 'update', 'en_US', 'An important update is required for WooCommerce', 'This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(53, 'paypal-braintree-sdk-depreciation-2025-02-20', 'update', 'en_US', 'Update required for your PayPal Braintree extension', 'To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(54, 'uk-vat-notice-2025-04-30', 'warning', 'en_US', 'UK VAT numbers are no longer supported', 'Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(55, 'payson-retirement-2025', 'update', 'en_US', 'Payson Form Retirement', 'Svea Bank is discontinuing the Payson service; the last date for transactions is August 31, 2025. As a result, the Payson Form extension has been removed from WooCommerce.com. Documentation remains available.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(56, 'paypal-braintree-sdk-depreciation-2025-05-30', 'update', 'en_US', 'Action required: Update the PayPal Braintree extension', 'Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.', '{}', 'pending', 'woocommerce.com', '2025-12-30 18:45:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(57, 'paypal-carding-recaptcha-dec-25', 'update', 'en_US', 'Activate PayPal fraud management', 'PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.', '{}', 'unactioned', 'woocommerce.com', '2025-12-30 20:13:08', NULL, 0, 'plain', '', 1, 0, 'info'),
(58, 'ppcp-recaptcha-protection-note', 'info', 'en_US', 'Activate PayPal fraud management', 'PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.', '{}', 'unactioned', 'woocommerce-paypal-payments/woocommerce-paypal-payments.php', '2025-12-30 18:56:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(59, 'wc-payments-notes-set-https-for-checkout', 'info', 'en_US', 'Enable secure checkout', 'Enable HTTPS on your checkout pages to display all available payment methods and protect your customers data.', '{}', 'unactioned', 'woocommerce-payments', '2025-12-30 19:16:22', NULL, 0, 'plain', '', 0, 0, 'info'),
(60, 'wc-admin-launch-checklist', 'info', 'en_US', 'Έτοιμοι να ξεκινήσετε το κατάστημά σας;', 'Για να σιγουρευτούμε ότι δεν θα έχετε αυτό το δυσάρεστο συναίσθημα του \"κάτι έχω ξεχάσει\", έχουμε συγκεντρώσει μία λίστα με όλα τα απαραίτητα πριν την επίσημη έναρξη.', '{}', 'unactioned', 'woocommerce-admin', '2026-03-08 16:25:04', NULL, 0, 'plain', '', 0, 0, 'info'),
(61, 'RIN-WC-Security-Update-admin-update-March-2026', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>Update to WooCommerce 10.5.3 or the latest version to resolve a security issue.</strong> This update addresses a vulnerability in WooCommerce versions 5.4 to 10.5.2 that could have permitted unauthorized admin account access. See the <a href=\"https://developer.woocommerce.com/2026/03/02/store-api-vulnerability-patched-in-woocommerce-5-4/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2026-03-08 16:25:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(62, 'USPS_Scan_Form_Mar2026', 'marketing', 'en_US', 'New: Save time shipping with USPS SCAN Form', 'USPS SCAN Form consolidates multiple shipments into one scannable sheet. Hand off all your orders at once — no more scanning packages individually. Select “Create SCAN Form” under your orders to try it today.', '{}', 'pending', 'woocommerce.com', '2026-03-13 06:39:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(64, 'gla-complete-setup', 'info', 'en_US', 'Reach more shoppers with product feed on Google', 'Finish setting up Google for WooCommerce to list your products on Google for free and promote them with ads.', '{}', 'unactioned', 'gla', '2026-03-21 17:23:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(65, 'wc-admin-manage-orders-on-the-go', 'info', 'en_US', 'Διαχειριστείτε τις παραγγελίες σας δρόμο', 'Αναζητήστε παραγγελίες, πληροφορίες πελάτη κι επεξεργαστείτε επιστροφές χρημάτων με ένα κλικ, με την εφαρμογή Woo.', '{}', 'unactioned', 'woocommerce-admin', '2026-07-21 14:18:59', NULL, 0, 'plain', '', 0, 0, 'info'),
(66, 'woo-dotcom-course-2026-06-09', 'marketing', 'en_US', 'Learn how to build your store with WooCommerce', 'In this free course, we\'ll help you set up and run your online store with clear, practical guidance.', '{}', 'pending', 'woocommerce.com', '2026-07-21 14:19:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(67, 'stripe-woo-gateway-update-july2026', 'update', 'en_US', 'An important update is required for Stripe for WooCommerce', '<strong>A critical update is required for Stripe for WooCommerce</strong> to address an issue that could lead to fraudulent payment totals. Please update your extension to the latest version immediately.', '{}', 'pending', 'woocommerce.com', '2026-07-21 14:19:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(68, '3pdmigration_paytrace_fortis', 'marketing', 'en_US', 'Important update about your Paytrace Gateway', 'Paytrace Gateway is being phased out of the WooCommerce.com Marketplace. Nothing changes right now, and your store will continue to work as usual. You’ll receive a retirement notice closer to the date. When you\'re ready to migrate, we recommend Fortis Payments — their team offers step-by-step migration guidance to help', '{}', 'pending', 'woocommerce.com', '2026-07-21 14:19:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(69, '3pdmigration_paytrace_visa', 'marketing', 'en_US', 'Important update about your Paytrace Gateway', 'Paytrace Gateway is being phased out of the WooCommerce.com Marketplace. Nothing changes right now, and your store will continue to work as usual. You’ll receive a retirement notice closer to the date. As a replacement, we recommend Visa Acceptance Solutions — accept popular payment methods in 97% of territories.', '{}', 'pending', 'woocommerce.com', '2026-07-21 14:19:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(70, 'wc-admin-orders-milestone', 'info', 'en_US', 'Συγχαρητήρια για την επεξεργασία 10 παραγγελιών!', 'Φτάσατε στο ορόσημο των 10 παραγγελιών! Τα πηγαίνετε περίφημα. Περιηγηθείτε σε μερικές ιστορίες επιτυχίας με το WooCommerce για έμπνευση.', '{\"current_milestone\":10}', 'unactioned', 'woocommerce-admin', '2026-07-22 16:36:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(71, 'mollie_incentive_h2_2026_PL', 'marketing', 'en_US', 'Localize your checkout with Mollie Payments', 'Boost conversions with BLIK and Przelewy24, alongside Europe’s most popular options, with Mollie’s smooth and reliable checkout experience. Sign up today and process up to PLN 50 000 with 0% fees until December 31. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2026-07-22 16:36:22', NULL, 0, 'plain', '', 0, 0, 'info'),
(72, 'googleforwoocommerce_q2_2026_row_incentive', 'marketing', 'en_US', 'Choose one of three Google Ads signup offers', 'New to Google Ads? Launch your first campaign and get a budget boost with one of three signup offers. Choose the offer that fits your monthly budget and start reaching more customers in more places. Offer for new advertisers only. Terms apply.', '{}', 'pending', 'woocommerce.com', '2026-07-24 12:34:21', NULL, 0, 'plain', '', 0, 0, 'info'),
(73, 'klaviyo_q3_2026', 'marketing', 'en_US', 'Attn Woo: Klaviyo Customer Hub is here', 'Drive revenue and reduce your support burden by giving customers a single place to manage their orders, returns, subscriptions, loyalty, and more. Enable Customer Hub in your Klaviyo dashboard today, available on all paid plans.', '{}', 'pending', 'woocommerce.com', '2026-07-30 08:38:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(74, 'mollie_incentive_h2_2026_sweden', 'marketing', 'en_US', 'Localize your checkout with Mollie Payments', 'Sell more with Swish, Klarna, and Europe’s other most popular options, using Mollie’s smooth and reliable checkout experience. Sign up today and process up to SEK 50,000 with 0% fees until December 31. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2026-09-09 13:35:45', NULL, 0, 'plain', '', 0, 0, 'info');
